import os
from typing import Dict, Any, Optional
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential

class InvoiceValidator:
    def __init__(self):
        endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
        key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
        if not endpoint or not key:
            raise ValueError("Missing Azure Document Intelligence credentials")
        self.client = DocumentIntelligenceClient(endpoint, AzureKeyCredential(key))

    def extract_and_validate(self, document_path: str, required_fields: list) -> Dict[str, Any]:
        with open(document_path, "rb") as f:
            poller = self.client.begin_analyze_document(
                "prebuilt-invoice",
                AnalyzeDocumentRequest(bytes_source=f.read())
            )
        result = poller.result()

        if not result.documents:
            raise ValueError("No invoice document detected")

        doc = result.documents[0]
        fields = doc.fields

        validation_results = {
            "missing_fields": [],
            "low_confidence_fields": [],
            "extracted_data": {},
            "all_present": False
        }

        for field_name in required_fields:
            if field_name not in fields:
                validation_results["missing_fields"].append(field_name)
                continue

            field = fields[field_name]
            confidence = field.confidence if field.confidence else 0.0
            value = field.value if field.value else None

            validation_results["extracted_data"][field_name] = {
                "value": value,
                "confidence": confidence
            }

            if confidence < 0.8:
                validation_results["low_confidence_fields"].append(field_name)

        validation_results["all_present"] = len(validation_results["missing_fields"]) == 0

        return validation_results

def validate_invoice_fields(document_path: str, required_fields: list) -> Dict[str, Any]:
    validator = InvoiceValidator()
    return validator.extract_and_validate(document_path, required_fields)
